only=sys.argv[1:]
for name,v in SETS.items():
    if only and name not in only: continue
    im=clean(SRC+name+'.png',OUT+name+'_clean.jpg',inpaint_leaders=False)
    im=erase_boxes(im,v['box']); cv2.imwrite(OUT+v['id']+'.jpg',im,[cv2.IMWRITE_JPEG_QUALITY,90])
    h,w=im.shape[:2]; ov=cv2.resize(im,(1400,int(h*1400/w)),interpolation=cv2.INTER_AREA); H,W=ov.shape[:2]
    for i,(la,uk,x,y) in enumerate(v['items'],1):
        cx,cy=int(x*W/100),int(y*H/100); cv2.circle(ov,(cx,cy),9,(255,255,255),-1); cv2.circle(ov,(cx,cy),9,(0,0,220),2); cv2.putText(ov,str(i),(cx+11,cy+5),cv2.FONT_HERSHEY_SIMPLEX,0.55,(0,0,220),2,cv2.LINE_AA)
    leg=255*np.ones((H,460,3),np.uint8)
    for i,(la,uk,x,y) in enumerate(v['items'],1): cv2.putText(leg,f'{i} {la}'[:48],(6,20+i*22),cv2.FONT_HERSHEY_SIMPLEX,0.45,(0,0,0),1,cv2.LINE_AA)
    cv2.imwrite(OV+v['id']+'.png',cv2.hconcat([ov,leg])); print(v['id'],w,h,len(v['items']))
json.dump({k:{kk:vv for kk,vv in v.items() if kk!='box'} for k,v in SETS.items()},open('sobo3/musc_sets.json','w'),ensure_ascii=False,indent=1)
